package com.onndetect.detection.visual

import com.onndetect.inference.LiteRTInferenceEngine
import com.onndetect.inference.MappedModel
import com.onndetect.inference.ModelLoader
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

/**
 * Training/serving contract tests for the optional Tier-2 forensic VLM (`Engine D`).
 *
 * The parity fixture is generated by
 * `ml/scripts/train_forensic_vlm_colab_t4.py --export-parity-fixture` and contains UNTRAINED
 * random weights. It verifies the JSON schema and the 13-output projection, not detection quality.
 */
class OnDemandForensicVlmAnalyzerContractTest {

    private val siglip = "siglip_probe_int8.tflite"

    private fun fixtureJson(): String {
        val stream = javaClass.classLoader!!.getResourceAsStream("forensic_vlm_policy_parity_fixture.json")
        assertNotNull("Parity fixture missing from test resources", stream)
        return stream!!.bufferedReader().use { it.readText() }
    }

    private fun engine(): LiteRTInferenceEngine = LiteRTInferenceEngine(object : ModelLoader {
        override fun loadMapped(fileName: String): MappedModel =
            throw UnsupportedOperationException("No models are loaded in contract tests")
    })

    private fun floats(arr: org.json.JSONArray) = FloatArray(arr.length()) { arr.getDouble(it).toFloat() }

    @Test
    fun policyBundleAndHeadProjectionMatchPythonExport() {
        val json = fixtureJson()
        val bundle = OnDemandForensicVlmAnalyzer.PolicyBundle.fromJson(json)
        val head = requireNotNull(bundle.headContract)
        assertEquals(OnDemandForensicVlmAnalyzer.RUBRIC_AXES, head.axes)

        val probe = JSONObject(json).getJSONObject("parity_probe")
        val hLast = floats(probe.getJSONArray("h_last"))
        val expected = probe.getJSONObject("expected_full")

        val pred = OnDemandForensicVlmAnalyzer.projectWithHeadContract(hLast, head)
        assertEquals(expected.getDouble("class_logit").toFloat(), pred.classLogit, 1e-4f)
        assertEquals(expected.getDouble("class_prob").toFloat(), pred.classProb, 1e-4f)
        val expF = floats(expected.getJSONArray("forgery_logits_6d"))
        val expC = floats(expected.getJSONArray("authentic_counter_logits_6d"))
        for (i in 0 until 6) {
            assertEquals("forgery axis $i", expF[i], pred.forgeryLogits6d[i], 1e-4f)
            assertEquals("counter axis $i", expC[i], pred.authenticCounterLogits6d[i], 1e-4f)
        }

        val maskArr = probe.getJSONArray("applicable_mask_6d")
        val mask = BooleanArray(6) { maskArr.getBoolean(it) }
        val masked = OnDemandForensicVlmAnalyzer.projectWithHeadContract(hLast, head, mask)
        val expMasked = probe.getJSONArray("expected_masked_forgery_logits_6d")
        for (i in 0 until 6) {
            if (expMasked.isNull(i)) {
                assertTrue("axis $i must be NaN when masked", masked.forgeryLogits6d[i].isNaN())
            } else {
                assertEquals(expMasked.getDouble(i).toFloat(), masked.forgeryLogits6d[i], 1e-4f)
            }
        }
    }

    @Test
    fun rejectsUnknownSchemaVersion() {
        val bad = fixtureJson().replace("onn-forensic-vlm-policy-v1", "onn-forensic-vlm-policy-v0")
        val failed = runCatching { OnDemandForensicVlmAnalyzer.PolicyBundle.fromJson(bad) }.isFailure
        assertTrue(failed)
    }

    @Test
    fun infeasiblePolicyNeverEscalates() {
        val policy = OnDemandForensicVlmAnalyzer.RoutingPolicyConfig(feasible = false)
        val route = OnDemandForensicVlmAnalyzer.routeWithPolicy(
            policy = policy,
            fastFusionProb = policy.decisionThresholdDev, // exactly on the boundary
            srmCalibratedScore = 0.95f,
            vfmProbeScore = 0.05f, // strong cross-engine conflict
            hotspotZScore = 5f,
        )
        assertFalse(route.invokeOnDeviceVlm)
        assertEquals("routing_policy_infeasible", route.triggerReason)
    }

    @Test
    fun feasiblePolicyEscalatesOnBoundaryUsingLearnedThresholds() {
        val policy = OnDemandForensicVlmAnalyzer.PolicyBundle.fromJson(fixtureJson()).routingPolicy
        val route = OnDemandForensicVlmAnalyzer.routeWithPolicy(
            policy = policy,
            fastFusionProb = policy.decisionThresholdDev,
            srmCalibratedScore = 0.5f,
            vfmProbeScore = 0.5f,
        )
        assertTrue(route.invokeOnDeviceVlm)
        assertEquals("ambiguous_fast_margin", route.triggerReason)
    }

    @Test
    fun leasedProjectionBlocksSiglipDuringPrefillAndReleasesAfterwards() {
        val eng = engine()
        val bundle = OnDemandForensicVlmAnalyzer.PolicyBundle.fromJson(fixtureJson())
        val hLast = floats(JSONObject(fixtureJson()).getJSONObject("parity_probe").getJSONArray("h_last"))
        var blockedDuringPrefill = false
        val outcome = OnDemandForensicVlmAnalyzer.executeLeasedProjection(
            inferenceEngine = eng,
            policyBundle = bundle,
            fastFusionProb = 0.55f,
            diagnosticOnly = true,
        ) {
            blockedDuringPrefill = eng.isModelBlocked(siglip)
            hLast
        }
        assertTrue("SigLIP must be blocked while the VLM prefill runs", blockedDuringPrefill)
        assertFalse("SigLIP must be unblocked after the lease closes", eng.isModelBlocked(siglip))
        assertEquals("diagnosticOnly must preserve the specialist score", 0.55f, outcome.posteriorProb, 1e-6f)
        assertTrue(outcome.vlmDialecticalProb in 0f..1f)
    }

    @Test
    fun leaseIsReleasedWhenPrefillThrows() {
        val eng = engine()
        val bundle = OnDemandForensicVlmAnalyzer.PolicyBundle.fromJson(fixtureJson())
        val result = runCatching {
            OnDemandForensicVlmAnalyzer.executeLeasedProjection(eng, bundle, fastFusionProb = 0.5f) {
                throw IllegalStateException("prefill failed")
            }
        }
        assertTrue(result.isFailure)
        assertFalse(eng.isModelBlocked(siglip))
        // A fresh lease must be obtainable after the failure.
        eng.acquireExclusiveVlmSession().close()
    }

    @Test
    fun overlappingExclusiveLeasesAreRejected() {
        val eng = engine()
        val first = eng.acquireExclusiveVlmSession()
        try {
            eng.acquireExclusiveVlmSession()
            fail("A second overlapping lease must be rejected")
        } catch (expected: IllegalStateException) {
            // expected
        }
        assertTrue("Rejected second lease must not release the first lease's block", eng.isModelBlocked(siglip))
        first.close()
        assertFalse(eng.isModelBlocked(siglip))
    }

    @Test
    fun explanationCitesOnlyEvaluatedAxesAndNoHardcodedClaims() {
        val outcome = OnDemandForensicVlmAnalyzer.fuseDialecticalLogits(
            fastFusionProb = 0.7f,
            forgeryLogits6d = floatArrayOf(1.2f, Float.NaN, 0.4f, Float.NaN, Float.NaN, Float.NaN),
            authenticCounterLogits6d = floatArrayOf(-0.3f, Float.NaN, 0.1f, Float.NaN, Float.NaN, Float.NaN),
        )
        assertEquals(listOf("anatomical_geometry", "surface_micro_texture"), outcome.evaluatedAxes)
        val text = outcome.dialecticalExplanation.lowercase()
        assertFalse(text.contains("bokeh"))
        assertFalse(text.contains("physics_illumination"))
        assertFalse(text.contains("boundary_halo_seam"))
    }
}
